// Independent Session50 audit. Only the original merged order-eight TSV is input.
// Degree-bucket exhaustive canonicalization (not refinement canonicalization).
// Full attachment-subset orbits use explicit original-label automorphisms.
// Child refinement uses in-neighbor partition splitting from a single cell.
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
using Rows=vector<unsigned>;
long long checks=0, canon_calls=0, canon_orders=0, auto_candidates=0;
void req(bool b,const string&s){++checks;if(!b)throw runtime_error(s);}
int pc(unsigned x){return __builtin_popcount(x);}
Rows decode(uint32_t x,int n){Rows r(n);int k=n*(n-1)/2;for(int i=0;i<n;++i)for(int j=i+1;j<n;++j){--k;if(x&(1u<<k))r[i]|=1u<<j;else r[j]|=1u<<i;}return r;}
void valid(const Rows&r){int n=r.size();for(int i=0;i<n;++i){req(!(r[i]>>n),"row outside vertex set");req(!(r[i]&(1u<<i)),"loop");for(int j=0;j<i;++j)req(((r[i]>>j)&1)!=((r[j]>>i)&1),"pair orientation");}}
vector<vector<int>> degree_cells(const Rows&r){map<int,vector<int>> b;for(int v=0;v<(int)r.size();++v)b[pc(r[v])].push_back(v);vector<vector<int>> a;for(auto&[d,c]:b)a.push_back(c);return a;}
template<class F>void each_order(const vector<vector<int>>&cells,F f){vector<int> p;function<void(int)> go=[&](int k){if(k==(int)cells.size()){f(p);return;}auto c=cells[k];do{p.insert(p.end(),c.begin(),c.end());go(k+1);p.resize(p.size()-c.size());}while(next_permutation(c.begin(),c.end()));};go(0);}
uint32_t canonical(const Rows&r){req(r.size()<=8,"no child canonicalization");++canon_calls;uint32_t best=UINT32_MAX;each_order(degree_cells(r),[&](const vector<int>&p){++canon_orders;uint32_t z=0;for(int i=0;i<(int)p.size();++i)for(int j=i+1;j<(int)p.size();++j)z=(z<<1)|((r[p[i]]>>p[j])&1);best=min(best,z);});return best;}
vector<vector<int>> automorphisms(const Rows&r){auto cells=degree_cells(r);vector<int> base;for(auto&c:cells)base.insert(base.end(),c.begin(),c.end());vector<vector<int>> out;each_order(cells,[&](const vector<int>&p){++auto_candidates;vector<int> g(r.size());for(int j=0;j<(int)p.size();++j)g[base[j]]=p[j];for(int i=0;i<(int)r.size();++i)for(int j=0;j<i;++j)if(((r[i]>>j)&1)!=((r[g[i]]>>g[j])&1))return;out.push_back(g);});req(!out.empty(),"identity automorphism");return out;}
unsigned action(unsigned m,const vector<int>&g){unsigned z=0;for(int i=0;i<(int)g.size();++i)if(m&(1u<<i))z|=1u<<g[i];return z;}
vector<unsigned> orbit_representatives(const vector<vector<int>>&aut,int n){vector<unsigned> out;vector<bool> seen(1<<n);for(unsigned m=0;m<(1u<<n);++m)if(!seen[m]){out.push_back(m);set<unsigned> orbit;for(auto&g:aut){unsigned z=action(m,g);seen[z]=true;orbit.insert(z);}req(aut.size()%orbit.size()==0,"subset orbit stabilizer");}req(count(seen.begin(),seen.end(),true)==(1<<n),"orbit cover");return out;}
Rows extension(const Rows&r,unsigned mask){Rows a=r;a.push_back(mask);int n=r.size();for(int v=0;v<n;++v)if(!(mask&(1u<<v)))a[v]|=1u<<n;return a;}
vector<unsigned> stable(const Rows&r){int n=r.size();vector<unsigned> cells{(1u<<n)-1};while(true){vector<unsigned> split;for(unsigned c:cells){map<vector<int>,unsigned> groups;for(int v=0;v<n;++v)if(c&(1u<<v)){vector<int> sig;unsigned incoming=((1u<<n)-1)^(r[v]|(1u<<v));for(unsigned b:cells)sig.push_back(pc(incoming&b));groups[sig]|=1u<<v;}for(auto&[s,b]:groups)split.push_back(b);}if(split.size()==cells.size())return split;cells=split;}}
Rows deleted(const Rows&a,int v){Rows b;for(int i=0;i<(int)a.size();++i)if(i!=v){unsigned low=a[i]&((1u<<v)-1);unsigned high=(a[i]>>(v+1))<<v;b.push_back(low|high);}return b;}
int main(int argc,char**argv){try{req(argc==3,"usage: audit source.tsv output-prefix");string prefix=argv[2];ifstream f(argv[1]);req(bool(f),"input open");string s;getline(f,s);map<int,uint32_t> codes;int merged=0,self=0;while(getline(f,s)){istringstream q(s);int mid,ia,ib;uint32_t a,b;long long fibre,blue;q>>mid>>ia>>ib>>a>>b>>fibre>>blue;req(bool(q),"TSV parse");req(mid==merged++,"merged ids");for(auto[id,code]:vector<pair<int,uint32_t>>{{ia,a},{ib,b}}){req(!codes.count(id)||codes[id]==code,"repeated code");codes[id]=code;}if(ia==ib)++self;}
vector<Rows> parents;vector<vector<vector<int>>> auts;set<uint32_t> keys;map<uint32_t,int> key_index;map<int,int> ah;long long mass=0;vector<int> almost;ofstream detail(prefix+"-parents.tsv");detail<<"source_id\tcanonical_degree_code\taut_order\tsubset_orbits\tupper\troot1\troot3\troot5\troot7\troot9\n";long long U=0,P=0;array<long long,10> hist{};map<string,long long> partitions;for(auto[id,code]:codes){req(id==(int)parents.size(),"ordinary ids");Rows r=decode(code,8);valid(r);uint32_t key=canonical(r);req(keys.insert(key).second,"distinct ordinary classes");key_index[key]=id;auto aut=automorphisms(r);req(40320%aut.size()==0,"parent orbit mass integral");mass+=40320/aut.size();ah[aut.size()]++;if(all_of(r.begin(),r.end(),[](unsigned z){return pc(z)==3||pc(z)==4;}))almost.push_back(id);auto reps=orbit_representatives(aut,8);array<long long,10> local{};long long u=0;for(unsigned mask:reps){Rows t=extension(r,mask);auto cells=stable(t);int z=0;vector<int> sizes;for(auto c:cells){req(pc(c)%2==1,"odd stable cells");sizes.push_back(pc(c));if(c&256)z=pc(c);}req(z>0,"marked root found");local[z]++;u+=z;sort(sizes.begin(),sizes.end());string shape;for(auto x:sizes)shape+=to_string(x)+",";partitions[shape]++;}P+=reps.size();U+=u;for(int z=0;z<10;++z)hist[z]+=local[z];detail<<id<<'\t'<<key<<'\t'<<aut.size()<<'\t'<<reps.size()<<'\t'<<u;for(int z:{1,3,5,7,9})detail<<'\t'<<local[z];detail<<'\n';parents.push_back(r);auts.push_back(aut);}
req(mass==(1ll<<28),"complete labelled parent universe");req(2*merged-self==(int)parents.size(),"converse merge counts");long long parent_canon_calls=canon_calls;map<uint32_t,int> reg_index;for(int k=0;k<(int)almost.size();++k)reg_index[canonical(parents[almost[k]])]=k;vector<vector<int>> D(almost.size(),vector<int>(almost.size()));long long trace=0;for(int k=0;k<(int)almost.size();++k){auto r=parents[almost[k]];unsigned mask=0;for(int v=0;v<8;++v)if(pc(r[v])==4)mask|=1u<<v;req(pc(mask)==4,"four high-degree vertices");Rows t=extension(r,mask);for(unsigned x:t)req(pc(x)==4,"regular extension");for(int v=0;v<9;++v){auto key=canonical(deleted(t,v));req(reg_index.count(key),"regular deletion points to almost-regular parent");D[k][reg_index.at(key)]++;}req(accumulate(D[k].begin(),D[k].end(),0)==9,"reroot row sum");trace+=D[k][k];}ofstream matrix(prefix+"-regular.tsv");matrix<<"source\ttarget\tmultiplicity\n";for(int i=0;i<(int)D.size();++i)for(int j=0;j<(int)D.size();++j)if(D[i][j])matrix<<i<<'\t'<<j<<'\t'<<D[i][j]<<'\n';int regclasses=0;vector<int> seen(D.size());map<string,int> profiles;for(int i=0;i<(int)D.size();++i)if(!seen[i]){++regclasses;vector<int> support;vector<int> orbits;int size=0;for(int j=0;j<(int)D.size();++j)if(D[i][j]){support.push_back(j);seen[j]=1;orbits.push_back(D[i][j]);size+=D[i][j];}req(size==9,"support orbit sizes sum nine");for(int j:support)req(D[j]==D[i],"reroot component rows agree");sort(orbits.begin(),orbits.end());string profile;for(int z:orbits)profile+=to_string(z)+",";profiles[profile]++;}req(trace==9*regclasses,"regular trace class identity");long long Ereg=9*((long long)almost.size()-regclasses),E=Ereg+128;req((U-E)%9==0,"corrected trace divisible");ofstream out(prefix+".json");out<<"{\n\"status\":\"PASS\",\n\"merged_classes\":"<<merged<<",\n\"self_converse_classes\":"<<self<<",\n\"parent_classes\":"<<parents.size()<<",\n\"parent_mass\":"<<mass<<",\n\"pointed_states\":"<<P<<",\n\"upper_trace\":"<<U<<",\n\"almost_regular_parents\":"<<almost.size()<<",\n\"regular_trace\":"<<trace<<",\n\"regular_classes\":"<<regclasses<<",\n\"regular_error\":"<<Ereg<<",\n\"total_error\":"<<E<<",\n\"predicted_nine\":"<<(U-E)/9<<",\n\"checks\":"<<checks<<",\n\"parent_canonical_calls\":"<<parent_canon_calls<<",\n\"regular_canonical_calls\":"<<canon_calls-parent_canon_calls<<",\n\"canonical_degree_orders\":"<<canon_orders<<",\n\"automorphism_candidates\":"<<auto_candidates<<",\n\"root_cell_histogram\":{";bool first=true;for(int z=0;z<10;++z)if(hist[z]){if(!first)out<<',';first=false;out<<'\"'<<z<<"\":"<<hist[z];}out<<"},\n\"aut_order_histogram\":{";first=true;for(auto[x,y]:ah){if(!first)out<<',';first=false;out<<'\"'<<x<<"\":"<<y;}out<<"},\n\"stable_partition_histogram\":{";first=true;for(auto[x,y]:partitions){if(!first)out<<',';first=false;out<<'\"'<<x<<"\":"<<y;}out<<"},\n\"regular_orbit_profiles\":{";first=true;for(auto[x,y]:profiles){if(!first)out<<',';first=false;out<<'\"'<<x<<"\":"<<y;}out<<"}\n}\n";cout<<"PASS U9="<<U<<" Ereg="<<Ereg<<" E9="<<E<<" A9="<<(U-E)/9<<"\n";
}catch(const exception&e){cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
